import { SchemaForm } from '@/components/schema';
import app from '@/store/app';
import { Button, Card, Divider, Form, Message, Space, Tabs, Modal, Drawer, Alert } from "@arco-design/web-react";
import React, { useEffect, useMemo, useState } from 'react';
import styles from './index.module.less';
import { AsyncButton } from '@/components/custom';
import ajax from '@/utils/ajax';
import store from './store';
import { SchemaFormItems } from '@/components/schema/Form';
import { FormGenerateContext } from 'react-converter-code';
import { EditImage, EditSchema
} from "@/components/custom";
import CustomVariableForm from '@/components/devs/customVariableForm';
import { generateReadableJson } from '@/utils/json';
import Hljs from '@/components/custom/Hljs';

const AppSetting = () => {

    const [form] = Form.useForm();

    const [schema, setSchema] = useState<JSONSchema>({});
    const [visible, setVisible] = useState(false);
    const [viewVisible, setViewVisible] = useState(false);

    const context = useMemo(() => {
        return {
            formats: {
                image: EditImage,
            }
        }
    },[])

    useEffect(() => {
        form.setFieldsValue(app.extraInfo.configuration);
    },[])

    return (
        <div className={styles.page}>
            <FormGenerateContext.Provider value={context}>
            <Form form={form} style={{ height: "100%" }} labelAlign="left">
            <Tabs
                extra={(
                    <Space style={{ justifyContent: "flex-end", width: "100%" }}>
                        <Button
                            onClick={() => {
                                form.resetFields()
                            }}
                        >重置</Button>
                        <AsyncButton
                            type="primary"
                            onClick={() => {
                                app.assignExtraInfo({
                                    configuration: {
                                        ...app.extraInfo.configuration,
                                        ...form.getFieldsValue(),
                                    }
                                })
                                return app.savaExtraInfo().then(() => {
                                    Message.success("保存成功")
                                });
                            }}
                        >保存修改</AsyncButton>
                        <Button type="primary" 
                            onClick={() => {
                                // console.log('configuration', app.extraInfo.configuration)
                                setViewVisible(true);
                            }}
                        >
                            查看配置
                        </Button>
                    </Space>
                )}
            >
                {app.projectInfo.customVariables.map((o, i) => {
                    return (
                        <Tabs.TabPane title={o.title} key={i} closable>
                            <CustomVariableForm
                                form={form}
                                schema={app.projectInfo.customVariables[i]}
                            />
                        </Tabs.TabPane>
                    )
                })}
                <Tabs.TabPane
                    key="custom"
                    title="自定义配置"
                >
                    <Card
                        style={{ width: 800 }}
                        className={styles['card']}
                        title="自定义变量"
                        extra={
                            <Button type="primary"
                                onClick={() => {
                                    setVisible(true);
                                    setSchema(app.extraInfo.customVariable)
                                }}
                            >更新配置</Button>
                        }
                    >
                        <SchemaFormItems
                            form={form}
                            cols={24}
                            schema={app.extraInfo.customVariable}
                        />
                    </Card>
                </Tabs.TabPane>
            </Tabs>
            </Form>
            <Modal title="自定义配置" style={{ width: 1200 }} visible={visible}
                onCancel={() => {
                    setVisible(false)
                }}
                onConfirm={() => {
                    if(schema.properties){
                        if(!Object.keys(schema.properties).every((key) => key.indexOf('cus_') == 0)){
                            Message.error("参数校验失败，参数必须以cus_ 开头")
                            return
                        }
                    }
                    setVisible(false);
                    app.assignExtraInfo({
                        customVariable: schema,
                    })
                }}
            >
                <Alert content="自定义配置参数必须以 cus_ 开头，例如 cus_name" />
                <EditSchema
                    notModel
                    showForm
                    value={schema}
                    onChange={setSchema}
                />
            </Modal>
            </FormGenerateContext.Provider>
            <Drawer visible={viewVisible} 
                footer={null}
                onCancel={() => {
                    setViewVisible(false)
                }}
                title="配置预览" width={800} placement="left"
            >
                <Hljs code="JavaScript" hiddenHeader >
                    { generateReadableJson(app.allVariablesSchema, app.extraInfo.configuration) }
                </Hljs>
            </Drawer>
        </div>
    )
}

export default AppSetting;